// Required: name, slug. Everything else has a sensible default so a minimal
// call (just name+slug) is enough to get a working, safe-by-default tenant.
const body = $input.first().json.body || {};

if (!body.name || String(body.name).trim() === '') {
  throw new Error('name is required');
}
if (!body.slug || String(body.slug).trim() === '') {
  throw new Error('slug is required');
}

const slug = String(body.slug).trim().toLowerCase();
if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(slug)) {
  throw new Error('slug must be lowercase letters, numbers and hyphens only (e.g. "acme-realty") -- it gets used in widget embed URLs');
}

const validPlans = ['trial', 'starter', 'pro', 'enterprise'];
const plan = body.plan || 'trial';
if (!validPlans.includes(plan)) {
  throw new Error(`plan must be one of: ${validPlans.join(', ')}`);
}

// Autonomy defaults are deliberately conservative (approval_required, not
// autonomous) -- see roadmap notes: new tenants should run in a shadow/
// approval-gated mode for their first stretch before anything is relaxed.
const defaultAutonomyRules = {
  send_email: { mode: 'approval_required' },
  book_appointment: { mode: 'approval_required' },
};
const defaultEscalationThresholds = { min_confidence: 0.6 };

return [{
  json: {
    name: String(body.name).trim(),
    slug,
    industry: body.industry ? String(body.industry).trim() : null,
    plan,
    timezone: body.timezone ? String(body.timezone).trim() : 'UTC',
    autonomy_rules: body.autonomy_rules || defaultAutonomyRules,
    escalation_thresholds: body.escalation_thresholds || defaultEscalationThresholds,
    lead_scoring_rubric: body.lead_scoring_rubric || {},
  }
}];

parameters.query:
insert into ai_config (tenant_id, autonomy_rules, escalation_thresholds, lead_scoring_rubric)
values ($1, $2, $3, $4)
returning *;

