// Builds the onboarding response, including the manual steps this workflow
// deliberately does NOT automate (see workflow 19's spec doc for why).
const tenant = $('Insert Tenant').first().json;
const instanceHost = $('Onboarding Webhook').first().json.headers?.host || 'YOUR-N8N-HOST';

return [{
  json: {
    success: true,
    tenant_id: tenant.id,
    slug: tenant.slug,
    name: tenant.name,
    next_steps: [
      'Connect this tenant\'s Google Calendar: currently a manual n8n credential setup, one Calendar OAuth2 credential per tenant is NOT yet supported dynamically at runtime -- same manual process used for the existing tenant(s).',
      'Connect this tenant\'s Gmail (if using the email agent): same manual limitation as Calendar -- one Gmail OAuth2 credential set up by hand in n8n, then set ai_config.connected_gmail_address to match.',
      `Seed an initial knowledge base document (optional): curl -X POST https://${instanceHost}/webhook/ingest-document -H "Content-Type: application/json" -d '{"tenant_slug": "${tenant.slug}", "title": "FAQ", "source_type": "faq", "text": "..."}'`,
      `Embed the chat widget on the tenant's site using tenant slug "${tenant.slug}" in the widget's data-tenant attribute.`,
    ],
  }
}];
